/* Ported from https://github.com/nenadmarkus/picojs (MIT). */

import type { GrayscaleImage } from "./pico";

export type LandmarkLocalizer = (
  row: number,
  col: number,
  scale: number,
  perturbCount: number,
  image: GrayscaleImage,
) => [row: number, col: number];

export function unpackLocalizer(bytes: Uint8Array): LandmarkLocalizer {
  const view = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength);
  let p = 0;
  const stageCount = view.getInt32(p, true);
  p += 4;
  const scaleMul = view.getFloat32(p, true);
  p += 4;
  const treesPerStage = view.getInt32(p, true);
  p += 4;
  const treeDepth = view.getInt32(p, true);
  p += 4;

  const leavesPerTree = 2 ** treeDepth;
  // Internal-node codes only — no root padding in the lploc format.
  const codesPerTree = 4 * leavesPerTree - 4;
  const totalTrees = stageCount * treesPerStage;

  const treeCodes = new Int8Array(totalTrees * codesPerTree);
  // Two predictions per leaf (row delta, col delta).
  const treePreds = new Float32Array(totalTrees * leavesPerTree * 2);

  for (let t = 0; t < totalTrees; t++) {
    treeCodes.set(bytes.subarray(p, p + codesPerTree), t * codesPerTree);
    p += codesPerTree;
    for (let l = 0; l < leavesPerTree; l++) {
      const base = (t * leavesPerTree + l) * 2;
      treePreds[base + 0] = view.getFloat32(p, true);
      p += 4;
      treePreds[base + 1] = view.getFloat32(p, true);
      p += 4;
    }
  }

  function localizeOnce(
    rowIn: number,
    colIn: number,
    scaleIn: number,
    image: GrayscaleImage,
  ): [number, number] {
    const { pixels, rows, cols, stride } = image;
    let row = rowIn;
    let col = colIn;
    let scale = scaleIn;

    for (let s = 0; s < stageCount; s++) {
      let dr = 0;
      let dc = 0;

      for (let t = 0; t < treesPerStage; t++) {
        const treeIndex = s * treesPerStage + t;
        const root = treeIndex * codesPerTree;
        let idx = 0;

        for (let d = 0; d < treeDepth; d++) {
          const r1 = Math.min(
            rows - 1,
            Math.max(0, (256 * row + treeCodes[root + 4 * idx + 0] * scale) >> 8),
          );
          const c1 = Math.min(
            cols - 1,
            Math.max(0, (256 * col + treeCodes[root + 4 * idx + 1] * scale) >> 8),
          );
          const r2 = Math.min(
            rows - 1,
            Math.max(0, (256 * row + treeCodes[root + 4 * idx + 2] * scale) >> 8),
          );
          const c2 = Math.min(
            cols - 1,
            Math.max(0, (256 * col + treeCodes[root + 4 * idx + 3] * scale) >> 8),
          );
          idx =
            2 * idx + 1 +
            (pixels[r1 * stride + c1] > pixels[r2 * stride + c2] ? 1 : 0);
        }

        const leafBase =
          (treeIndex * leavesPerTree + idx - (leavesPerTree - 1)) * 2;
        dr += treePreds[leafBase + 0];
        dc += treePreds[leafBase + 1];
      }

      row += dr * scale;
      col += dc * scale;
      scale *= scaleMul;
    }

    return [row, col];
  }

  return (row, col, scale, perturbCount, image) => {
    const rowSamples: number[] = [];
    const colSamples: number[] = [];
    for (let i = 0; i < perturbCount; i++) {
      const perturbedScale = scale * (0.925 + 0.15 * Math.random());
      const perturbedRow = row + scale * 0.15 * (0.5 - Math.random());
      const perturbedCol = col + scale * 0.15 * (0.5 - Math.random());
      const [r, c] = localizeOnce(
        perturbedRow,
        perturbedCol,
        perturbedScale,
        image,
      );
      rowSamples.push(r);
      colSamples.push(c);
    }
    rowSamples.sort((a, b) => a - b);
    colSamples.sort((a, b) => a - b);
    const mid = Math.round(perturbCount / 2);
    return [rowSamples[mid], colSamples[mid]];
  };
}

const PUPLOC_BASE64 =
  "";

export const localizePupil: LandmarkLocalizer = unpackLocalizer(
  Uint8Array.from(atob(PUPLOC_BASE64), (c) => c.charCodeAt(0)),
);
